<script type="module">
import { removeBackground } from 'https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm';

const $=id=>document.getElementById(id);
const picker=$('picker'),drop=$('drop'),selection=$('selection'),filegrid=$('filegrid'),count=$('count'),processBtn=$('process'),processing=$('processing'),editor=$('editor'),canvas=$('canvas'),ctx=canvas.getContext('2d'),canvasWrap=$('canvasWrap'),outputs=$('outputs'),outputList=$('outputList');
let files=[], currentFile=null, originalImage=null, cutoutImage=null, bgImage=null, bgMode='transparent', bgColor='#ffffff', bgGradient='linear-gradient(135deg,#635bff,#ec4899)', scale=1;
const tips=['High-contrast subjects usually produce the cleanest first-pass cutout.','Your image stays on this device while the AI model works.','The first run can take longer because the AI model may need to load.','After removal, try a solid color for profile photos or product shots.','A custom background photo can turn a simple cutout into a complete design.'];let tipIndex=0;
function esc(s){return s.replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function human(n){return n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(2)+' MB'}
function add(fs){files.push(...[...fs].filter(f=>/^image\/(png|jpeg|webp)$/.test(f.type)));renderFiles()}
function renderFiles(){filegrid.innerHTML='';count.textContent=files.length+' image'+(files.length===1?'':'s')+' selected';selection.style.display=files.length?'block':'none';files.forEach((f,i)=>{const u=URL.createObjectURL(f),d=document.createElement('div');d.className='file';d.innerHTML='<img src="'+u+'" alt=""><button class="remove-file" aria-label="Remove '+esc(f.name)+'">✕</button><div class="file-meta"><div class="fname">'+esc(f.name)+'</div><div class="fsize">'+human(f.size)+'</div></div>';d.querySelector('.remove-file').onclick=()=>{URL.revokeObjectURL(u);files.splice(i,1);renderFiles()};filegrid.appendChild(d)})}
picker.onchange=e=>{add(e.target.files);picker.value=''};$('choose').onclick=()=>picker.click();
['dragenter','dragover'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>add(e.dataTransfer.files));
$('clear').onclick=()=>{files=[];renderFiles();processing.style.display='none';editor.style.display='none';outputs.style.display='none'};$('newImage').onclick=()=>{editor.style.display='none';outputs.style.display='none';processing.style.display='none';selection.style.display=files.length?'block':'none';window.scrollTo({top:document.querySelector('.app').offsetTop-20,behavior:'smooth'})};
function progress(key,current,total){const pct=total?Math.max(0,Math.min(100,Math.round(current/total*100))):0;$('bar').style.width=pct+'%';$('pct').textContent=pct+'%';const stage=key.split(':').pop();const labels={decode:['Reading your image','Getting pixels ready for the AI'],inference:['Finding the subject','AI is separating foreground from background'],mask:['Refining the edges','Cleaning hair, clothes and fine details'],encode:['Finishing the cutout','Encoding your transparent result']};const l=labels[stage]||['Processing with AI','Working locally on your image'];$('aiTitle').textContent=l[0];$('aiDetail').textContent=l[1];$('stage').textContent=stage.charAt(0).toUpperCase()+stage.slice(1)}
function rotateTip(){ $('tip').textContent=tips[tipIndex%tips.length];tipIndex++ }setInterval(rotateTip,3600);
async function blobUrl(file){return URL.createObjectURL(file)}
async function loadImage(source){return new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=source})}
async function processOne(file){currentFile=file;originalImage=await loadImage(await blobUrl(file));progress('compute:decode',0,4);const blob=await removeBackground(file,{model:'isnet',output:{format:'image/png',quality:1},progress});cutoutImage=await loadImage(URL.createObjectURL(blob));renderCanvas()}
processBtn.onclick=async()=>{if(!files.length)return;processBtn.disabled=true;selection.style.display='none';processing.style.display='block';editor.style.display='none';outputs.style.display='none';rotateTip();outputList.innerHTML='';let ok=0;for(let i=0;i<files.length;i++){try{await processOne(files[i]);ok++;if(files.length>1){const url=canvas.toDataURL('image/png');const d=document.createElement('div');d.className='out-card';d.innerHTML='<img src="'+url+'" alt=""><div class="out-title">'+esc(files[i].name.replace(/\.[^.]+$/,'')+'-no-background.png')+'</div><a download="'+esc(files[i].name.replace(/\.[^.]+$/,'')+'-no-background.png')+'" href="'+url+'">⬇ Download transparent PNG</a>';outputList.appendChild(d)}}catch(e){const d=document.createElement('div');d.className='error';d.textContent='Could not process '+files[i].name+': '+(e?.message||e);outputList.appendChild(d)}}processing.style.display='none';if(ok){editor.style.display='block';if(files.length>1){outputs.style.display='block'}}processBtn.disabled=false;window.scrollTo({top:editor.offsetTop-30,behavior:'smooth'})};
function cssGradient(ctx,w,h,css){const m=css.match(/linear-gradient\(135deg,\s*(#[0-9a-fA-F]+),\s*(#[0-9a-fA-F]+)\)/);const g=ctx.createLinearGradient(0,0,w,h);if(m){g.addColorStop(0,m[1]);g.addColorStop(1,m[2])}else{g.addColorStop(0,'#635bff');g.addColorStop(1,'#ec4899')}return g}
function renderCanvas(){if(!cutoutImage)return;const max=1400,ratio=Math.min(1,max/Math.max(cutoutImage.naturalWidth,cutoutImage.naturalHeight));canvas.width=Math.max(1,Math.round(cutoutImage.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(cutoutImage.naturalHeight*ratio));ctx.clearRect(0,0,canvas.width,canvas.height);if(bgMode==='original'&&originalImage){ctx.drawImage(originalImage,0,0,canvas.width,canvas.height)}else if(bgMode==='color'){ctx.fillStyle=bgColor;ctx.fillRect(0,0,canvas.width,canvas.height)}else if(bgMode==='gradient'){ctx.fillStyle=cssGradient(ctx,canvas.width,canvas.height,bgGradient);ctx.fillRect(0,0,canvas.width,canvas.height)}else if(bgMode==='image'&&bgImage){ctx.drawImage(bgImage,0,0,canvas.width,canvas.height)}const w=canvas.width*scale,h=canvas.height*scale,x=(canvas.width-w)/2,y=(canvas.height-h)/2;ctx.drawImage(cutoutImage,x,y,w,h)}
function setMode(mode){bgMode=mode;document.querySelectorAll('.mode').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('colorPanel').style.display=mode==='color'?'block':'none';$('gradientPanel').style.display=mode==='gradient'?'block':'none';$('imagePanel').style.display=mode==='image'?'block':'none';renderCanvas()}
document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));document.querySelectorAll('.swatch[data-color]').forEach(b=>b.onclick=()=>{bgColor=b.dataset.color;$('color').value=bgColor;setMode('color')});$('color').oninput=e=>{bgColor=e.target.value;setMode('color')};document.querySelectorAll('.swatch[data-gradient]').forEach(b=>b.onclick=()=>{bgGradient=b.dataset.gradient;setMode('gradient')});$('pickBg').onclick=()=>$('color').click();$('uploadBgBtn').onclick=()=>$('bgPicker').click();$('bgPicker').onchange=async e=>{if(e.target.files[0]){bgImage=await loadImage(URL.createObjectURL(e.target.files[0]));setMode('image')}};$('scale').oninput=e=>{scale=Number(e.target.value)/100;$('scaleVal').textContent=e.target.value+'%';renderCanvas()};$('restore').onclick=()=>setMode('original');
function download(type){if(!currentFile)return;const mime=type==='png'?'image/png':'image/jpeg';let url=canvas.toDataURL(mime,type==='jpg'?0.92:1);const base=currentFile.name.replace(/\.[^.]+$/,'');const suffix=bgMode==='transparent'?'no-background':bgMode+'-background';const a=document.createElement('a');a.href=url;a.download=base+'-'+suffix+'.'+(type==='png'?'png':'jpg');a.click()}
$('downloadPng').onclick=()=>download('png');$('downloadJpg').onclick=()=>download('jpg');
</script>
</body>
</html>